def chunks(start, end, days: int):
    """Split a range into calendar-aligned windows.

    A year of 15-minute data in one request is a good way to get a timeout from
    energy-charts and a 400 from ENTSO-E (which caps most endpoints at a year
    anyway). days=0 means one request for the lot.
    """
    if not days:
        yield start, end
        return
    while start < end:
        stop = min(start + pd.DateOffset(days=days), end)
        yield start, stop
        start = stop


